/* Browser acceptance run (not part of `npm test`): drives the app against a local server with Playwright.
 *   MOCK_ARTIFACT=1 runs the same scenarios through the shared-database store (js/store/artifact.js) with an in-page mock of the claude.ai runtime.
 *   node server/seed.js && PORT=8099 node server/server.js &
 *   BASE=http://localhost:8099 node tests/e2e.acceptance.js
 * Covers the 17 acceptance scenarios of the workflow brief (A1–A17), the Audit & Control brief (C1–C16: imports, comparison, ranking, gaps, opportunity, gap vs loss, below-rate and below-cost flags, exception approval, pre-allocation audit, truck-days, negotiation priorities, recommendations, exports, no duplicated history), the Setup brief scenarios (B1–B10: LOB, KPI and
 * account mapping, ledger posting, workshop, trip P&L, revenue by LOB, financial closure, master data, OTD) end to end at UI level where practical and via the
 * store API otherwise, plus the retained checks of the earlier briefs (FMR status rules, double booking, waybill chain,
 * credit notes, role restrictions). The CDN is blocked, so the FMR upload uses the CSV fallback of the workbook reader. */
const fs = require('fs');
const path = require('path');
const { chromium } = require(process.env.PW || '/opt/node22/lib/node_modules/playwright');
