  for (const v of ['dashboard', 'crm', 'planning', 'tpl', 'trips', 'fleet', 'tat', 'fleetdash', 'dispatch', 'lostsales', 'rates', 'invoices', 'payments', 'reports', 'commercial', 'audit', 'clients', 'assets', 'users', 'settings']) await step(`view ${v} renders`, async () => { await go(v, 500); const title = await page.textContent('#view-title'); if (!title) throw new Error('no title'); const bad = await page.$('.notice.bad'); if (bad && /failed to render/.test(await bad.textContent())) throw new Error(await bad.textContent()); });

