    const planBlocked = await ev(async (id) => { const s = HB.app.store; const cur = s.state.requests.find((x) => x.id === id); try { await s.saveDoc('requests', { id, plan: { approvedQty: 1, approvedBy: 'ops', approvedAt: new Date().toISOString() }, status: 'Plan Approved' }, { expectedVersion: cur.version }); return 'accepted'; } catch (e) { return e.code || e.message; } }, unmappedId); if (planBlocked === 'accepted') throw new Error('plan approved on an unmapped route');
    // Operations maps and approves the route in the Route Master; the request becomes submittable
    await ev((id) => { const pl = HB.views.planning; const r = pl.requestRows(HB.app.store).find((x) => x.id === id); pl.editRoute(pl.ctx, null, { client: r.client, loadingPoint: r.loadingFrom, destination: r.destination, size: 'JUMBO', tonnage: '30T', kmOneWay: 1250, kmReturn: 1250, days: 8, offloading: 1, totalDays: 9, status: 'Approved', price: 4200000 }); }, unmappedId); await page.waitForSelector('#btn-save-route');
    await page.click('#btn-save-route'); await page.waitForTimeout(800);
