    const crmTry = await ev(async (id) => { const s = HB.app.store; const cur = s.state.requests.find((x) => x.id === id); try { await s.saveDoc('requests', { id, plan: { approvedQty: 1, vehicleType: 'JUMBO', approvedBy: 'crm', approvedAt: new Date().toISOString() }, status: 'Plan Approved' }, { expectedVersion: cur.version }); return 'accepted'; } catch (e) { return e.code; } }, reqId); if (crmTry === 'accepted') throw new Error('CRM approved a plan');
