    await ev((id) => HB.views.planning.planRequest(HB.views.planning.ctx, id), reqId); await page.waitForTimeout(300); if (await page.$('#planner-table')) throw new Error('station could allocate before plan approval'); if (!/approved/i.test(lastToast)) throw new Error('no guard message: ' + lastToast);
